func TestLv5_FreshEachPut(t *testing.T) {
	e := newEnv(t)
	ck := e.clerk("C1")
	e.net.Drop("C1", "rep", 1)
	var first, second Err
	within(t, 2*time.Second, "no_retry", say("Clerk 没有返回。", "The Clerk did not return."), func() {
		first = ck.Put("x", "v", 0)  // retried → ErrMaybe
		second = ck.Put("x", "w", 0) // first try refused → ErrVersion
	})
	if first != ErrMaybe {
		fail(t, "maybe_missing", say("第一个 Put 的回复丢了，重发后被拒绝，应该返回 ErrMaybe，你返回了 %q。", "The first Put's reply was lost and the resend was refused, so it should return ErrMaybe; you returned %q.", first))
	}
	if second != ErrVersion {
		fail(t, "maybe_sticky", say("第二个 Put 一次就送到了，却返回了 %q，应该是 ErrVersion。「是否重发过」要每个 Put 单独记，不能留到下一个 Put。", "The second Put got through on the first try but returned %q; it should be ErrVersion. Each Put tracks whether it was resent on its own; it must not carry over to the next Put.", second))
	}
}
